CREATE TABLE IF NOT EXISTS account_privacy (
 user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 last_seen text NOT NULL DEFAULT 'everyone' CHECK(last_seen IN('everyone','contacts','nobody')),
